struct Item { value: int }
mut seed := [] mut j := 0 while j < 2 { seed = push(seed, Item { value: 0 }) j += 1 }
mut state := seed seed = null
export func snapshot() { return state }
export func edit(n) { state[0] = Item { value: n } return n }

